/**
 * 递归查询子节点
 *
 * @param root
 * @param configuredMenuBoList
 * @return
 */
private List<ConfiguredMenuBo> getChildrensConfiguredMenu(ConfiguredMenuBo root, List<ConfiguredMenuBo> configuredMenuBoList) {
    return configuredMenuBoList.stream().filter(e -> Objects.equals(e.getParentId(), root.getId())).peek(
            e -> {
                e.setCategory(root.getCategory());  // 子树继承根分类
                e.setChildList(getChildrensConfiguredMenu(e, configuredMenuBoList));
            }
    ).sorted(Comparator.comparing(ConfiguredMenuBo::getSort)).collect(Collectors.toList());
}

/**
 * 组件菜单是否保留展示：同端保留、未区分旧组件保留、跨端隐藏
 *
 * @param menuGroup
 * @param targetEnd
 * @return
 */
private boolean isKeepComponentMenu(String menuGroup, String targetEnd) {
    if (StringUtils.isEmpty(targetEnd)) {
        return true;
    }
    if (StringUtils.isEmpty(menuGroup)) {
        return true;
    }
    return StringUtils.equals(resolveComponentEndType(menuGroup), targetEnd);
}
